class Solution {
    int get_score(int a, int b) {
        if (a == b) return 0;
        if ((a == 1 && b == 0) || (a == 0 && b == 2) || (a == 2 && b == 1)) return 1;
        return -1;
    }
public:
    int countWinningSequences(std::string s) {
        int MOD = 1000000007;
        int n = s.size();
        int offset = n;

        std::vector<std::vector<int>> dp(4, std::vector<int>(2 * n + 1, 0));
        dp[3][offset] = 1;

        for (char c : s) {
            int b = (c == 'F' ? 0 : (c == 'W' ? 1 : 2));
            std::vector<std::vector<int>> next_dp(4, std::vector<int>(2 * n + 1, 0));

            for (int last = 0; last < 4; ++last) {
                for (int diff = 0; diff <= 2 * n; ++diff) {
                    int count = dp[last][diff];
                    if (count == 0) continue;
                    for (int a = 0; a < 3; ++a) {
                        if (a != last) {
                            int new_diff = diff + get_score(a, b);
                            if (new_diff >= 0 && new_diff <= 2 * n) {
                                next_dp[a][new_diff] = (next_dp[a][new_diff] + count) % MOD;
                            }
                        }
                    }
                }
            }
            dp = std::move(next_dp);
        }

        int ans = 0;
        for (int last = 0; last < 3; ++last) {
            for (int diff = offset + 1; diff <= 2 * n; ++diff) {
                ans = (ans + dp[last][diff]) % MOD;
            }
        }
        return ans;
    }
};

class Solution {
    private final int MOD = 1_000_000_007;

    public int countWinningSequences(String s) {
        int n = s.length();
        int offset = n;
        int[][] dp = new int[4][2 * n + 1];
        dp[3][offset] = 1;

        for (int idx = 0; idx < n; idx++) {
            char c = s.charAt(idx);
            int b = (c == 'F' ? 0 : (c == 'W' ? 1 : 2));
            int[][] nextDp = new int[4][2 * n + 1];

            for (int last = 0; last < 4; last++) {
                for (int diff = 0; diff <= 2 * n; diff++) {
                    int count = dp[last][diff];
                    if (count == 0) continue;
                    for (int a = 0; a < 3; a++) {
                        if (a != last) {
                            int newDiff = diff + getScore(a, b);
                            if (newDiff >= 0 && newDiff <= 2 * n) {
                                nextDp[a][newDiff] = (nextDp[a][newDiff] + count) % MOD;
                            }
                        }
                    }
                }
            }
            dp = nextDp;
        }

        int ans = 0;
        for (int last = 0; last < 3; last++) {
            for (int diff = offset + 1; diff <= 2 * n; diff++) {
                ans = (ans + dp[last][diff]) % MOD;
            }
        }
        return ans;
    }

    private int getScore(int a, int b) {
        if (a == b) return 0;
        if ((a == 1 && b == 0) || (a == 0 && b == 2) || (a == 2 && b == 1)) return 1;
        return -1;
    }
}

